"use client";

import { useEffect, useState } from "react";

const BANNER_IMAGES = [
  {
    src: "/images/slide1.png",
    alt: "Product banner 1",
  },
  {
    src: "/images/slide2.png",
    alt: "Product banner 2",
  },
];

export default function ProductLaunch() {
  const [currentSlide, setCurrentSlide] = useState(0);

  const previousSlide = () => {
    setCurrentSlide((current) =>
      current === 0 ? BANNER_IMAGES.length - 1 : current - 1
    );
  };

  const nextSlide = () => {
    setCurrentSlide((current) =>
      current === BANNER_IMAGES.length - 1 ? 0 : current + 1
    );
  };

  // Automatically move to the next image every 5 seconds
  useEffect(() => {
    const interval = window.setInterval(() => {
      setCurrentSlide((current) =>
        current === BANNER_IMAGES.length - 1 ? 0 : current + 1
      );
    }, 5000);

    return () => window.clearInterval(interval);
  }, []);

  return (
    <section className="growware-banner-section">
      <div className="growware-banner-carousel">
        {BANNER_IMAGES.map((image, index) => (
          <div
            key={image.src}
            className={`growware-banner-slide ${
              index === currentSlide ? "active" : ""
            }`}
            aria-hidden={index !== currentSlide}
          >
            <img src={image.src} alt={image.alt} />
          </div>
        ))}

        <button
          type="button"
          className="growware-arrow growware-arrow-left"
          onClick={previousSlide}
          aria-label="Previous image"
        >
          &#8249;
        </button>

        <button
          type="button"
          className="growware-arrow growware-arrow-right"
          onClick={nextSlide}
          aria-label="Next image"
        >
          &#8250;
        </button>

        <div className="growware-dots">
          {BANNER_IMAGES.map((image, index) => (
            <button
              type="button"
              key={image.src}
              onClick={() => setCurrentSlide(index)}
              className={`growware-dot ${
                index === currentSlide ? "active-dot" : ""
              }`}
              aria-label={`Go to image ${index + 1}`}
              aria-current={index === currentSlide ? "true" : undefined}
            />
          ))}
        </div>
      </div>

      <style jsx>{`
        .growware-banner-section {
          width: 100%;
          margin: 0;
          padding: 0;
          overflow: hidden;
          background: #062c4c;
        }

        .growware-banner-carousel {
          position: relative;
          width: 100%;
          aspect-ratio: 16 / 7;
          overflow: hidden;
          background: #062c4c;
        }

        .growware-banner-slide {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          opacity: 0;
          visibility: hidden;
          transition: opacity 0.7s ease, visibility 0.7s ease;
          pointer-events: none;
        }

        .growware-banner-slide.active {
          opacity: 1;
          visibility: visible;
          pointer-events: auto;
        }

        .growware-banner-slide img {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: contain;
          object-position: center;
        }

        .growware-arrow {
          position: absolute;
          top: 50%;
          transform: translateY(-50%);
          z-index: 5;
          display: flex;
          align-items: center;
          justify-content: center;
          width: 48px;
          height: 48px;
          padding: 0;
          border: 1px solid rgba(255, 255, 255, 0.35);
          border-radius: 50%;
          background: rgba(2, 24, 42, 0.65);
          color: #fff;
          font-size: 34px;
          line-height: 1;
          cursor: pointer;
          transition: background 0.2s ease;
        }

        .growware-arrow:hover {
          background: rgba(0, 125, 205, 0.9);
        }

        .growware-arrow-left {
          left: 20px;
        }

        .growware-arrow-right {
          right: 20px;
        }

        .growware-dots {
          position: absolute;
          bottom: 18px;
          left: 50%;
          transform: translateX(-50%);
          z-index: 6;
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .growware-dot {
          width: 9px;
          height: 9px;
          padding: 0;
          border: none;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          cursor: pointer;
          transition: width 0.25s ease, background 0.25s ease;
        }

        .growware-dot.active-dot {
          width: 28px;
          border-radius: 999px;
          background: #28baff;
        }

        @media (max-width: 700px) {
          .growware-banner-carousel {
            aspect-ratio: 4 / 3;
          }

          .growware-banner-slide img {
            object-fit: contain;
          }

          .growware-arrow {
            width: 38px;
            height: 38px;
            font-size: 27px;
          }

          .growware-arrow-left {
            left: 10px;
          }

          .growware-arrow-right {
            right: 10px;
          }

          .growware-dots {
            bottom: 10px;
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .growware-banner-slide,
          .growware-arrow,
          .growware-dot {
            transition: none;
          }
        }
      `}</style>
    </section>
  );
}
